/** Deterministic template-agnostic grid compiler. Canonical coordinates are inches. */
export class GridContractError extends Error{constructor(code,message,details={}){super(message);this.name='GridContractError';this.code=code;this.details=Object.freeze({...details});}}
const fail=(c,m,d={})=>{throw new GridContractError(c,m,d)}; const fin=n=>typeof n==='number'&&Number.isFinite(n); const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const SLIDE_PRESETS=Object.freeze({standard:{width:13.333,height:7.5},classic:{width:10,height:7.5},portrait:{width:7.5,height:13.333},a4landscape:{width:11.694,height:8.268}});
function pageSize(page={}){const p=typeof page==='string'?SLIDE_PRESETS[page]:page; if(!p||!fin(+p.width)||!fin(+p.height)||p.width<=0||p.height<=0) fail('GRID_PAGE','Page requires positive finite width/height.',{page}); return {width:+p.width,height:+p.height};}
function normRegion(r,page){const x=+(r?.x??0),y=+(r?.y??0),width=+(r?.width??page.width),height=+(r?.height??page.height);if(![x,y,width,height].every(fin)||width<=0||height<=0||x<0||y<0||x+width>page.width+1e-9||y+height>page.height+1e-9)fail('GRID_REGION','Target region must be a positive rectangle within the page.',{r,page});return{x,y,width,height};}
function trackSizes(spec,count,total,gap){if(!Number.isInteger(count)||count<1||count>64)fail('GRID_TRACKS','Track count must be 1..64.',{count});const usable=total-gap*(count-1);if(usable<=0)fail('GRID_GAP','Gutters consume target region.',{total,gap,count}); if(spec==null)return Array(count).fill(usable/count); if(Array.isArray(spec)){if(spec.length!==count)fail('GRID_TRACKS','Explicit track sizes must match count.');const vals=spec.map(Number);if(vals.some(v=>!fin(v)||v<=0))fail('GRID_TRACKS','Track sizes must be positive finite.');const s=vals.reduce((a,b)=>a+b,0);return vals.map(v=>usable*v/s);} fail('GRID_TRACKS','Track spec must be null or array.');}
function sumTo(a,n){let s=0;for(let i=0;i<n;i++)s+=a[i];return s;}
export function findLargestEmptyRegion(pageInput, obstacles=[], options={}){const page=pageSize(pageInput);const pad=Math.max(0,Number(options.padding ?? 0.1));const obs=obstacles.filter(Boolean).map(o=>({x:clamp(+o.x||0,0,page.width),y:clamp(+o.y||0,0,page.height),width:Math.max(0,+o.width||0),height:Math.max(0,+o.height||0)}));
 const xs=[0,page.width],ys=[0,page.height];for(const o of obs){xs.push(clamp(o.x-pad,0,page.width),clamp(o.x+o.width+pad,0,page.width));ys.push(clamp(o.y-pad,0,page.height),clamp(o.y+o.height+pad,0,page.height));} xs.sort((a,b)=>a-b);ys.sort((a,b)=>a-b);let best={x:0,y:0,width:page.width,height:page.height,area:0};
 for(let xi=0;xi<xs.length-1;xi++)for(let xj=xi+1;xj<xs.length;xj++)for(let yi=0;yi<ys.length-1;yi++)for(let yj=yi+1;yj<ys.length;yj++){const r={x:xs[xi],y:ys[yi],width:xs[xj]-xs[xi],height:ys[yj]-ys[yi]};if(r.width<=0||r.height<=0)continue;const hit=obs.some(o=>r.x<o.x+o.width+pad&&r.x+r.width>o.x-pad&&r.y<o.y+o.height+pad&&r.y+r.height>o.y-pad);if(hit)continue;const area=r.width*r.height,centerPenalty=Math.abs((r.x+r.width/2)-page.width/2)+Math.abs((r.y+r.height/2)-page.height/2);const bestPenalty=Math.abs((best.x+best.width/2)-page.width/2)+Math.abs((best.y+best.height/2)-page.height/2);if(area>best.area+1e-9||(Math.abs(area-best.area)<1e-9&&centerPenalty<bestPenalty)){best={...r,area};}}
 return Object.freeze({x:best.x,y:best.y,width:best.width,height:best.height});}
export function compileGridLayout(input={}){const page=pageSize(input.page??'standard');const target=normRegion(input.targetRegion,page);const columns=Math.max(1,Math.trunc(input.columns??12)),rows=Math.max(1,Math.trunc(input.rows??6));const colGap=Math.max(0,Number(input.columnGap ?? input.gap ?? 0.08)),rowGap=Math.max(0,Number(input.rowGap ?? input.gap ?? 0.08));if(!fin(colGap)||!fin(rowGap))fail('GRID_GAP','Gutters must be finite.',{colGap,rowGap});const cs=trackSizes(input.columnSizes,columns,target.width,colGap),rs=trackSizes(input.rowSizes,rows,target.height,rowGap);const items=(input.items??[]).map((it,index)=>{const col=Math.trunc(it.col??0),row=Math.trunc(it.row??0),colSpan=Math.trunc(it.colSpan??1),rowSpan=Math.trunc(it.rowSpan??1);if(col<0||row<0||colSpan<1||rowSpan<1||col+colSpan>columns||row+rowSpan>rows)fail('GRID_ITEM','Item lies outside grid.',{index,it,columns,rows});const x=target.x+sumTo(cs,col)+colGap*col,y=target.y+sumTo(rs,row)+rowGap*row,width=cs.slice(col,col+colSpan).reduce((a,b)=>a+b,0)+colGap*(colSpan-1),height=rs.slice(row,row+rowSpan).reduce((a,b)=>a+b,0)+rowGap*(rowSpan-1);return Object.freeze({id:String(it.id??`item-${index+1}`),col,row,colSpan,rowSpan,x,y,width,height,nx:(x-target.x)/target.width,ny:(y-target.y)/target.height,nw:width/target.width,nh:height/target.height});});
 const overlaps=[];for(let i=0;i<items.length;i++)for(let j=i+1;j<items.length;j++){const a=items[i],b=items[j];if(a.x<b.x+b.width-1e-9&&a.x+a.width>b.x+1e-9&&a.y<b.y+b.height-1e-9&&a.y+a.height>b.y+1e-9)overlaps.push([a.id,b.id]);}if(overlaps.length&&!input.allowOverlap)fail('GRID_OVERLAP','Grid items overlap.',{overlaps});
 const fingerprint=JSON.stringify({page,target,columns,rows,colGap,rowGap,items:items.map(({id,col,row,colSpan,rowSpan})=>({id,col,row,colSpan,rowSpan}))});return Object.freeze({page:Object.freeze(page),targetRegion:Object.freeze(target),grid:Object.freeze({columns:Object.freeze({count:columns,sizes:Object.freeze(cs)}),rows:Object.freeze({count:rows,sizes:Object.freeze(rs)}),columnGap:colGap,rowGap}),placements:Object.freeze(items),warnings:Object.freeze([]),fingerprint});}
export function mapPlacementToRegion(p,target){return{x:target.x+p.nx*target.width,y:target.y+p.ny*target.height,width:p.nw*target.width,height:p.nh*target.height};}
